def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda v: sum(row.count(v) for row in grid))

    # Connected components of each non-background color.
    comps = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            cells = set()
            stack = [(r, c)]
            seen.add((r, c))
            while stack:
                y, x = stack.pop()
                cells.add((y, x))
                for yy, xx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy, xx))
                        stack.append((yy, xx))
            comps.append((color, cells))

    # Select the component that best resembles a long right-angle line.
    def l_score(cells):
        best = 0
        for r, c in cells:
            for dr, dc in ((-1, 0), (1, 0)):
                for hr, hc in ((0, -1), (0, 1)):
                    n = 1
                    y = r + dr
                    while (y, c) in cells:
                        n += 1
                        y += dr
                    x = c + hc
                    while (r, x) in cells:
                        n += 1
                        x += hc
                    best = max(best, n)
        return best

    if not comps:
        return out
    marker_color, marker = max(comps, key=lambda item: l_score(item[1]))

    # Find the elbow and the directions of the two arms.
    elbow = None
    dirs = None
    best = -1
    for r, c in marker:
        for vr in (-1, 1):
            for hc in (-1, 1):
                a = 1
                y = r + vr
                while (y, c) in marker:
                    a += 1
                    y += vr
                b = 1
                x = c + hc
                while (r, x) in marker:
                    b += 1
                    x += hc
                if a + b > best:
                    best = a + b
                    elbow, dirs = (r, c), (vr, hc)

    er, ec = elbow
    vr, hc = dirs

    # Recolor the closest component lying outside the L's interior quadrant.
    candidates = []
    for color, cells in comps:
        if color == marker_color:
            continue
        # Interior is the quadrant extending along both arms from the elbow.
        outside = {
            (r, c) for r, c in cells
            if not ((r-er)*vr > 0 and (c-ec)*hc > 0)
        }
        if not outside:
            continue
        dist = min(abs(r-y) + abs(c-x) for r, c in outside for y, x in marker)
        candidates.append((dist, color, cells))

    if candidates:
        _, _, chosen = min(candidates, key=lambda z: z[0])
        for r, c in chosen:
            out[r][c] = marker_color
    return out
